    enum E { E0, E1 };
    struct EnumMember { char lead; enum E value; char tail; };
    typedef unsigned char Aligned __attribute__((aligned(8)));
    struct Bits { Aligned a:1; Aligned b:1; char tail; };
    struct Nested { char lead; struct Bits members[2]; char tail; };
    struct Three { char a[3]; };
    typedef _Atomic(struct Three) AtomicThree;
    typedef _Atomic(struct Bits) AtomicBits;
_Static_assert((sizeof(struct EnumMember))==12,"sizeof(struct EnumMember)");
_Static_assert((_Alignof(struct EnumMember))==4,"_Alignof(struct EnumMember)");
_Static_assert((sizeof(struct Nested))==48,"sizeof(struct Nested)");
_Static_assert((__builtin_offsetof(struct Nested,tail))==40,"__builtin_offsetof(struct Nested,tail)");
_Static_assert((sizeof(struct Bits))==16,"sizeof(struct Bits)");
_Static_assert((__builtin_offsetof(struct Bits,tail))==9,"__builtin_offsetof(struct Bits,tail)");
_Static_assert((sizeof(AtomicThree))==3,"sizeof(AtomicThree)");
_Static_assert((_Alignof(AtomicThree))==1,"_Alignof(AtomicThree)");
_Static_assert((sizeof(AtomicBits))==16,"sizeof(AtomicBits)");
